      const headers = ["Loại", "Frame", "Item ID", "Annotation ID", "Chi tiết"];
      const lines = [headers.join("	")];
      for (const i of report.dataIssues) {
        lines.push(
          [i.kind, i.frame, i.item_id, i.ann_id, i.detail].map(escapeTsvField).join("	")
        );
      }
